// src/utils/request.js
import axios from "axios";
import { ElMessage } from "element-plus";
import userStore from "@/stores/userStore"; // 导入 Vuex userStore
// 确保使用 import.meta.env 访问环境变量
const apiBaseUrl = import.meta.env.VITE_API_BASE_URL;
const request = axios.create({
  baseURL: apiBaseUrl,
  timeout: 5000,
});

request.interceptors.request.use(
  (config) => {
    const token = userStore.state.user ? userStore.state.user.token : null; // 从 Vuex state 中获取 token
    if (token) {
      config.headers["Authorization"] = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  },
);

request.interceptors.response.use(
  (response) => {
    return response.data;
  },
  (error) => {
    ElMessage.error(error.response?.data?.message || "请求错误");
    return Promise.reject(error);
  },
);

export default request;
